import { HALLS, RESTAURANT_HOURS, RESTAURANT_TABLES, SLOTS, EVENT_TYPES } from "../lib/data";
import { estimateTotal, formatSum, type Booking, type BookingStatus, type HistoryEntry } from "../lib/bookings";
import type { Catalog } from "../lib/program";
import { addDaysISO, weekdayISO } from "../lib/time";

/**
 * Demo data for trying the site, the cabinet and the admin. Generated by `pnpm db:seed`
 * and removed by `pnpm db:clear-demo`; rows carry seeded/demo flags, real requests never do.
 */

export const PAST_DAYS = 60;
export const FUTURE_DAYS = 120;

const FIRST = ["Дилноза", "Тимур", "Шахноза", "Азиз", "Мадина", "Бехзод", "Нигора", "Жасур", "Камола", "Санжар", "Гульнора", "Отабек", "Феруза", "Рустам", "Малика", "Улугбек", "Севара", "Фаррух", "Лола", "Сардор"];
const LAST = ["Каримов", "Рахимов", "Юсупов", "Алимов", "Ташкентов", "Саидов", "Назаров", "Хамидов", "Усманов", "Мирзаев", "Абдуллаев", "Исмоилов", "Турсунов", "Ахмедов"];
const FEMALE = new Set(["Дилноза", "Шахноза", "Мадина", "Нигора", "Камола", "Гульнора", "Феруза", "Малика", "Севара", "Лола"]);

/** The guest accounts documented in README for trying the cabinet. */
export const DEMO_CLIENTS = [
  { name: "Дилноза Каримова", phone: "+998 90 123 45 67" },
  { name: "Тимур Рахимов", phone: "+998 93 555 12 34" },
];

/** Admin accounts documented in README; the seed creates them only if they are missing. */
export const DEMO_ADMINS = [
  { id: "u-admin", login: "admin", name: "Администратор", password: "admin" },
  { id: "u-manager", login: "manager", name: "Шахноза, менеджер", password: "manager" },
];

function mulberry(seed: number) {
  return () => {
    seed |= 0;
    seed = (seed + 0x6d2b79f5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * @param today  Tashkent "YYYY-MM-DD"
 * @param taken  "hall|date|slot" of real banquets already in the database, kept free of demo rows
 */
export function demoBookings(today: string, catalog: Catalog, taken: Set<string>): Booking[] {
  const rand = mulberry(20261023);
  const pick = <T,>(arr: readonly T[]) => arr[Math.floor(rand() * arr.length)];
  const out: Booking[] = [];
  let seq = 0;
  const now = Date.now();

  const person = () => {
    const f = pick(FIRST);
    const l = pick(LAST);
    const phone = `+998 9${Math.floor(rand() * 10)} ${String(Math.floor(rand() * 1000)).padStart(3, "0")} ${String(Math.floor(rand() * 100)).padStart(2, "0")} ${String(Math.floor(rand() * 100)).padStart(2, "0")}`;
    return { name: `${f} ${FEMALE.has(f) ? `${l}а` : l}`, phone };
  };

  const make = (b: Omit<Booking, "id" | "history" | "createdAt" | "updatedAt" | "source">, createdDaysBefore: number): Booking => {
    const created = new Date(`${addDaysISO(b.date, -createdDaysBefore)}T10:00:00+05:00`);
    const createdAt = (created.getTime() > now ? new Date(now - 86_400_000) : created).toISOString();
    const history: HistoryEntry[] = [{ at: createdAt, by: "client", text: "Заявка отправлена с сайта" }];
    if (b.status !== "new" && b.status !== "cancelled") history.push({ at: createdAt, by: "admin", text: "Менеджер подтвердил дату" });
    if (b.tastingAt) history.push({ at: createdAt, by: "admin", text: "Назначена дегустация" });
    if (b.prepayment) history.push({ at: createdAt, by: "admin", text: `Получена предоплата ${formatSum(b.prepayment)}` });
    if (b.status === "done") history.push({ at: new Date(`${b.date}T23:30:00+05:00`).toISOString(), by: "system", text: "Торжество проведено" });
    if (b.status === "cancelled") history.push({ at: createdAt, by: "client", text: "Заявка отменена" });
    return { ...b, id: `seed-${seq++}`, source: "seed", history, createdAt, updatedAt: createdAt };
  };

  const free = (hall: string, date: string, slot: string) => !taken.has(`${hall}|${date}|${slot}`);
  const hold = (hall: string, date: string, slot: string) => taken.add(`${hall}|${date}|${slot}`);

  // Demo guests first, so random rows never take their slots.
  const demo = [
    make({ code: "YS-2026", hall: "grand", date: addDaysISO(today, 24), slot: "evening", guests: 420, ...DEMO_CLIENTS[0], eventType: "Свадьба", comment: "Детский стол на 20 человек", status: "prepaid", prepayment: 45_000_000, tastingAt: `${addDaysISO(today, -3)}T15:00`, extras: { menu: ["menu-dastarkhan"], decor: ["decor-flowers"], show: ["show-orchestra", "show-sparklers"], cake: ["cake-roses"], photo: ["photo-photographer"] }, demo: true }, 30),
    make({ code: "YS-2027", hall: "small", date: addDaysISO(today, 6), slot: "day", guests: 120, ...DEMO_CLIENTS[0], eventType: "Никох", status: "confirmed", tastingAt: `${addDaysISO(today, 2)}T13:00`, demo: true }, 9),
    make({ code: "YS-7341", hall: "small", date: addDaysISO(today, 41), slot: "evening", guests: 180, ...DEMO_CLIENTS[1], eventType: "Юбилей", comment: "60 лет отцу, нужен экран для видео", status: "new", demo: true }, 1),
  ];
  for (const b of demo) {
    if (!free(b.hall, b.date, b.slot)) continue;
    out.push(b);
    hold(b.hall, b.date, b.slot);
  }

  for (let i = -PAST_DAYS; i < FUTURE_DAYS; i++) {
    const iso = addDaysISO(today, i);
    const past = iso < today;
    const dow = weekdayISO(iso);
    const weekend = dow === 0 || dow === 5 || dow === 6;

    for (const hall of HALLS) {
      if (hall.id === "restaurant") {
        for (const h of RESTAURANT_HOURS) {
          const peak = h >= "18:00" && h <= "21:00";
          const base = (weekend ? 0.55 : 0.3) + (peak ? 0.3 : 0);
          const n = Math.round(rand() * base * RESTAURANT_TABLES);
          for (let t = 0; t < n; t++) {
            out.push(make({ code: `YS-${1000 + Math.floor(rand() * 9000)}`, hall: "restaurant", date: iso, slot: h, guests: 2 + Math.floor(rand() * 6), ...person(), status: past ? "done" : "confirmed", seeded: true }, 1 + Math.floor(rand() * 5)));
          }
        }
        continue;
      }
      for (const slot of SLOTS) {
        const p = weekend ? (slot.id === "evening" ? 0.85 : 0.5) : slot.id === "evening" ? 0.35 : 0.15;
        if (rand() >= p || !free(hall.id, iso, slot.id)) continue;
        const guests = Math.round(hall.guestsMax * (0.5 + rand() * 0.4));
        const r = rand();
        let status: BookingStatus;
        if (past) status = r < 0.05 ? "cancelled" : "done";
        else if (i <= 14) status = r < 0.7 ? "prepaid" : "confirmed";
        else status = r < 0.04 ? "new" : r < 0.55 ? "confirmed" : "prepaid";
        const total = estimateTotal({ hall: hall.id, guests }, catalog) ?? 0;
        const prepaid = status === "prepaid" || status === "done";
        out.push(
          make(
            {
              code: `YS-${1000 + Math.floor(rand() * 9000)}`,
              hall: hall.id,
              date: iso,
              slot: slot.id,
              guests,
              ...person(),
              eventType: pick(EVENT_TYPES.slice(0, 6)),
              status,
              prepayment: prepaid ? Math.round((total * 0.3) / 1_000_000) * 1_000_000 : undefined,
              tastingAt: status !== "new" && status !== "cancelled" ? `${addDaysISO(iso, -10)}T15:00` : undefined,
              seeded: true,
            },
            20 + Math.floor(rand() * 70),
          ),
        );
        // A cancelled demo row does not hold the slot, like in real life.
        if (status !== "cancelled") hold(hall.id, iso, slot.id);
      }
    }
  }
  return out;
}
